steps.content:
// exec_policy.rs — check_command(["cargo", "check"])

// 步骤 1: parse commands
(commands, used_complex_parsing) =
  commands_for_exec_policy(&["cargo", "check"])
→ (["cargo", "check"], false)

// 步骤 2: execpolicy 规则引擎匹配
policy.evaluate(["cargo", "check"], &opts)
→ matchedRules: []  // 无规则匹配

// 步骤 3: 启发式回退
render_decision_for_unmatched_command(
  approval_policy,
  sandbox_policy,
  command,
  ...
)

// render_decision_for_unmatched_command()

is_known_safe_command(["cargo", "check"])
→ is_safe_to_call_with_exec(["cargo", "check"])
→ "cargo" ∉ 安全白名单
→ false

command_might_be_dangerous(["cargo", "check"])
→ is_dangerous_to_call_with_exec(["cargo", "check"])
→ "cargo" ∉ 危险命令列表
→ false

// approval_policy = AskForApproval::OnFailure
match approval_policy {
  AskForApproval::OnFailure => Decision::Allow
  // 依赖沙箱做实际隔离
}
→ Decision::Allow

// sandboxing/src/manager.rs — SandboxManager::select_initial()

should_require_platform_sandbox(
  file_system_policy,    // FileSystemSandboxKind::Restricted
  network_sandbox_policy, // NetworkSandboxPolicy::Restricted
  has_managed_network,   // false
)
→ true  // Restricted fs policy 需要沙箱

// Linux:
get_platform_sandbox(windows_sandbox_enabled=false)
→ Some(SandboxType::LinuxSeccomp)

// manager.transform() 构建实际 argv:
// codex-linux-sandbox \
//   --sandbox-policy-cwd /home/user/myproject \
//   --command-cwd /home/user/myproject \
//   --sandbox-policy '{"WorkspaceWrite":{...}}' \
//   --file-system-sandbox-policy '{...}' \
//   --network-sandbox-policy '"Restricted"' \
//   -- cargo check

// exec_policy.rs — check_command(["git", "push", "origin", "main"])

// BANNED_PREFIX_SUGGESTIONS 检查:
static BANNED_PREFIX_SUGGESTIONS: &[&[&str]] = &[
  &["git"],
  // ...（shell、python、sudo 等都在列表中）
];
// "git" 命中 → HeuristicsRuleMatch { decision: Prompt }

// 同时: command_might_be_dangerous(["git","push",..])
// → find_git_subcommand() → "push"
// → git_subcommand_requires_prompt("push") → true
// → Prompt

// 合并: Prompt
→ Decision::Prompt

// AgentEvent::ExecApprovalRequest 发送给 TUI
ApprovalRequest {
  call_id: "call_03",
  command: ["git", "push", "origin", "main"],
  reason: "git 命令需要批准",
  proposed_amendment: Some(
    ExecPolicyAmendment {
      prefix: ["git", "push"],
      decision: Allow,
    }
  ),
}
// 用户可选:
//   ① 本次批准 (ReviewDecision::Approved)
//   ② 批准并记住 (ReviewDecision::ApprovedExecpolicyAmendment)
//   ③ 拒绝 (ReviewDecision::Denied)

// 用户选择: ReviewDecision::ApprovedExecpolicyAmendment
// → exec_policy.rs:blocking_append_allow_prefix_rule()
//    写入到 ~/.codex/rules/default.rules:
//
prefix_rule(
  pattern = ["git", "push"],
)
// 下次同类命令自动 Allow，不再询问
